daemon.pseudocode:
def daemonize():
    if fork() > 0:
        exit(0)  # 부모 종료 → 자식은 init에 입양
    setsid()  # 새 세션 리더, 제어 터미널 분리
    if fork() > 0:
        exit(0)  # 세션 리더 아님 → 터미널 재획득 불가
    chdir('/')  # 마운트 해제 방해 방지
    umask(0)  # 파일 생성 권한 마스크 초기화
    for fd in (0, 1, 2):
        close(fd)
    open('/dev/null')  # 표준 입출력 재지정
    while True:
        handle(wait_request())  # 요청 대기 루프

data-deduplication.pseudocode:
def dedup_write(data, store, index, chunker):
    recipe = []  # 파일 복원용 청크 해시 목록
    for c in chunker(data):  # 고정 또는 가변 길이 청킹
        h = sha256(c)
        if h not in index:  # 처음 보는 청크만 저장
            index[h] = store.append(c)
        recipe.append(h)  # 중복이면 참조만 추가
    return recipe

def restore(recipe, store, index):
    return b''.join(store.read(index[h]) for h in recipe)
